import {ToolRegistry} from './registry.js';

describe('ToolRegistry caching', () => {
  const createSchema = (): Record<string, unknown> => ({
    type: 'object',
    properties: {count: {type: 'number'}},
    required: ['count'],
  });

  it('caches compiled validators for function-valued schemas by schema object reference', async () => {
    const registry = new ToolRegistry();
    const schemaInstance = createSchema();

    registry.register(
      () => ({
        name: 'test_tool',
        description: 'test',
        inputSchema: schemaInstance,
      }),
      async () => 'ok'
    );

    const response1 = await registry.execute('test_tool', {count: 'not-a-number'});
    schemaInstance.required = [];
    const response2 = await registry.execute('test_tool', {count: 'not-a-number'});

    expect({
      firstCallFailed: response1.result.includes('validation failed'),
      firstCallMentionsCount: response1.result.includes('count'),
      secondCallFailed: response2.result.includes('validation failed'),
    }).toEqual({
      firstCallFailed: true,
      firstCallMentionsCount: true,
      secondCallFailed: true,
    });
  });

  it('invokes the executor once and passes the input object through unchanged when validation succeeds', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'passthrough_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {id: {type: 'number'}},
          required: ['id'],
        },
      },
      async input => {
        executorCalls += 1;
        receivedInput = input;
        return 'ok';
      }
    );

    const inputObj = {id: 42, extra: 'kept', nested: {flag: true}};
    const response = await registry.execute('passthrough_tool', inputObj);

    expect({
      response,
      executorCalls,
      receivedInput,
    }).toEqual({
      response: {result: 'ok'},
      executorCalls: 1,
      receivedInput: {id: 42, extra: 'kept', nested: {flag: true}},
    });
  });

  it('throws Unknown tool when executing an unregistered tool', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nonexistent', {})).rejects.toThrow('Unknown tool: nonexistent');
  });

  it('compiles static tool inputSchema at register time and reuses it without re-reading', async () => {
    const registry = new ToolRegistry();
    const schemaInstance = createSchema();

    registry.register(
      {
        name: 'static_tool',
        description: 'test',
        inputSchema: schemaInstance,
      },
      async () => 'ok'
    );

    const response1 = await registry.execute('static_tool', {count: 'not-a-number'});
    schemaInstance.required = [];
    const response2 = await registry.execute('static_tool', {count: 'not-a-number'});

    expect({
      response1Failed: response1.result.includes('validation failed'),
      response2Failed: response2.result.includes('validation failed'),
    }).toEqual({
      response1Failed: true,
      response2Failed: true,
    });
  });
});

import Ajv from 'ajv';
import type {ValidateFunction, Options} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const ajvOptions: Options & {strict?: boolean} = {
  strict: false,
};
const ajv = new Ajv(ajvOptions);

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaCache = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      return ajv.compile(schema);
    } catch (e) {
      throw new Error(`Failed to compile inputSchema for tool ${name}: ${e instanceof Error ? e.message : String(e)}`, {
        cause: e,
      });
    }
  }

  private getValidator(tool: StoredTool, name: string): ValidateFunction {
    if (tool.staticValidator) return tool.staticValidator;
    const resolved = this.resolveDefinition(tool.definitionSource);
    const schemaObj = resolved.inputSchema;
    let validator = this.schemaCache.get(schemaObj);
    if (!validator) {
      validator = this.compileSchema(name, schemaObj);
      this.schemaCache.set(schemaObj, validator);
    }
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      staticValidator = this.compileSchema(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a tool, returning a ToolResponse for rejected input or throwing for an unknown name (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const validator = this.getValidator(tool, name);
    if (!validator(input)) {
      const errorMsg = ajv.errorsText(validator.errors);
      return {result: `Input validation failed: ${errorMsg}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

