it('drives a stub provider through a rejected tool call followed by a corrected retry, and processMessage resolves', async () => {
  let capturedToolResult = '';
  const mockProvider: AIProvider = {
    async *sendMessage(params: SendMessageParams) {
      // Find the last message
      const lastMsg = params.messages[params.messages.length - 1];
      if (lastMsg && lastMsg.role === 'user' && typeof lastMsg.content === 'object' && Array.isArray(lastMsg.content)) {
        const toolResultBlock = lastMsg.content.find((c: any) => c.type === 'tool_result');
        if (toolResultBlock && toolResultBlock.type === 'tool_result' && toolResultBlock.content) {
          capturedToolResult = (toolResultBlock.content as any).result;
        }
      }

      if (!capturedToolResult) {
        yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {wrong: 'yes'}}};
        yield {type: 'stop', stopReason: 'tool_use'};
      } else {
        yield {type: 'text', text: 'got the rejection'};
        yield {type: 'stop', stopReason: 'end_turn'};
      }
    }
  };

  const orchestrator = createChatOrchestrator(
    mockProvider,
    promptBuilder,
    registryReturning({result: 'Input validation failed: invalid'}),
  );

  const result = await orchestrator.processMessage(createSession('ask'));
  expect(result).toBe('got the rejection');
  expect(capturedToolResult).toBe('Input validation failed: invalid');
});

